import{_ as a,o as t,c as l,al as i}from"./chunks/framework.7vp1BMOE.js";const d=JSON.parse('{"title":"Complete Vehicles (Multicopter)","description":"","frontmatter":{},"headers":[],"relativePath":"en/complete_vehicles_mc/index.md","filePath":"en/complete_vehicles_mc/index.md"}'),o={name:"en/complete_vehicles_mc/index.md"};function r(s,e,c,n,p,h){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="complete-vehicles-multicopter" tabindex="-1">Complete Vehicles (Multicopter) <a class="header-anchor" href="#complete-vehicles-multicopter" aria-label="Permalink to &quot;Complete Vehicles (Multicopter)&quot;">​</a></h1><p>This section contains information about fully assembled ready to fly (RTF) or near-RTF vehicles that either run PX4 by default or can/may be usable with PX4.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This is a small subset of vehicles that can run PX4. You can find others on <a href="https://px4.io/ecosystem/commercial-systems/" target="_blank" rel="noreferrer">px4.io</a> and in the <a href="./../airframes/airframe_reference">Airframes Reference</a>.</p></div><h2 id="drone-development-kits-reference-platforms" tabindex="-1">Drone Development Kits/Reference Platforms <a class="header-anchor" href="#drone-development-kits-reference-platforms" aria-label="Permalink to &quot;Drone Development Kits/Reference Platforms&quot;">​</a></h2><p>This section lists drone kits that are intended as platforms for further development. They may come either fully assembled or in parts.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Kits certified by the PX4 team are listed in <a href="./../dev_kits/">PX4 Developer Kits</a>.</p></div><ul><li><a href="./../complete_vehicles_mc/modalai_starling">ModalAI VOXL 2 Starling PX4 Development Drone</a> - SLAM development drone supercharged by VOXL 2 and PX4 (<a href="./../dev_kits/">Official PX4 Developer Kit</a>)</li><li><a href="./../complete_vehicles_mc/droneblocks_dexi">DroneBlocks DEXI 5</a> - STEM/development kit with optical flow and Raspberry Pi companion computer (<a href="./../dev_kits/">Official PX4 Developer Kit</a>)</li><li><a href="./../complete_vehicles_mc/px4_vision_kit">PX4 Vision DevKit</a> - Multicopter used for PX4 computer vision development</li></ul><h2 id="px4-preinstalled" tabindex="-1">PX4 Preinstalled <a class="header-anchor" href="#px4-preinstalled" aria-label="Permalink to &quot;PX4 Preinstalled&quot;">​</a></h2><p>This section lists vehicles that are sold fully assembled and ready to fly (RTF), with PX4 installed.</p><ul><li><a href="./../complete_vehicles_mc/mindracer210">MindRacer 210</a></li><li><a href="./../complete_vehicles_mc/nanomind110">NanoMind 110</a></li><li><a href="./../complete_vehicles_mc/amov_F410_drone">Amovlab F410</a></li></ul><h2 id="px4-compatible" tabindex="-1">PX4 Compatible <a class="header-anchor" href="#px4-compatible" aria-label="Permalink to &quot;PX4 Compatible&quot;">​</a></h2><p>This section lists vehicles where you can update the software to run PX4.</p><ul><li><a href="./../complete_vehicles_mc/holybro_kopis2">Holybro Kopis 2</a></li><li><a href="./../complete_vehicles_mc/crazyflie21">Bitcraze Crazyflie 2.1</a></li></ul><h2 id="custom-px4" tabindex="-1">Custom PX4 <a class="header-anchor" href="#custom-px4" aria-label="Permalink to &quot;Custom PX4&quot;">​</a></h2><p>This section contains consumer vehicles that run a <em>custom</em> version of PX4 (supported by their vendors). These may or may not be updatable to run &quot;vanilla&quot; PX4.</p><ul><li><a href="https://us.yuneec.com/typhoon-h-plus/" target="_blank" rel="noreferrer">Yuneec Typhoon H Plus</a></li><li><a href="https://px4.io/project/yuneec-mantis-q/" target="_blank" rel="noreferrer">Yuneec Mantis Q</a></li><li><a href="https://px4.io/project/yuneec-h520-hexacopter/" target="_blank" rel="noreferrer">Yuneec H520</a></li><li><a href="https://px4.io/project/aerosense-aerobo/" target="_blank" rel="noreferrer">AeroSense Aerobo (AS-MC02-P)</a></li></ul><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../frames_multicopter/kits">Kits (MC)</a></li><li><a href="./../frames_multicopter/diy_builds">DIY Builds</a></li><li><a href="./../complete_vehicles_vtol/">Complete Vehicles (VTOL)</a></li><li><a href="./../complete_vehicles_fw/">Complete Vehicles (Fixed-Wing)</a></li></ul>',18)])])}const f=a(o,[["render",r]]);export{d as __pageData,f as default};
